    20	    private static final BigDecimal MAX_DISCOUNT_RATE = new BigDecimal("0.30");
    21	
    22	    private final Map<String, Coupon> byCode;
    23	
    24	    public Coupons(List<Coupon> coupons) {
    25	        this.byCode = coupons.stream().collect(Collectors.toMap(Coupon::code, Function.identity()));
    26	    }
