     8	import org.springframework.stereotype.Service;
     9	
    10	import com.loja.orders.catalog.Product;
    11	import com.loja.orders.catalog.ProductRepository;
    12	import com.loja.orders.common.ApiException;
    13	import com.loja.orders.common.ErrorCode;
    14	import com.loja.orders.common.Money;
    15	import com.loja.orders.coupon.Coupon;
    16	import com.loja.orders.coupon.CouponContext;
    17	import com.loja.orders.coupon.Coupons;
    18	import com.loja.orders.order.OrderItem;
    19	import com.loja.orders.payment.PaymentContext;
    20	import com.loja.orders.payment.PaymentMethod;
    21	import com.loja.orders.payment.PaymentMethods;
    22	import com.loja.orders.payment.PaymentTerms;
    23	import com.loja.orders.shipping.ShippingOption;
    24	import com.loja.orders.shipping.ShippingOptions;
    25	import com.loja.orders.shipping.ShippingQuote;
    26	import com.loja.orders.shipping.ShippingRequest;
    27	
    28	/**
    29	 * Calcula o resumo da compra, conferindo os dados na ordem combinada e recusando no primeiro
    30	 * problema. O resumo mostrado antes de confirmar e o do pedido registrado saem daqui.
    31	 */
    32	@Service
    33	public class CheckoutCalculator {
    34	
    35	    private static final Pattern ZIP_CODE = Pattern.compile("\\d{8}");
    36	
    37	    private final ProductRepository products;
    38	    private final ShippingOptions shippingOptions;
    39	    private final Coupons coupons;
    40	    private final PaymentMethods paymentMethods;
    41	
    42	    public CheckoutCalculator(ProductRepository products, ShippingOptions shippingOptions, Coupons coupons,
    43	            PaymentMethods paymentMethods) {
    44	        this.products = products;
    45	        this.shippingOptions = shippingOptions;
    46	        this.coupons = coupons;
    47	        this.paymentMethods = paymentMethods;
    48	    }
    49	
    50	    public CheckoutSummary calculate(CheckoutRequest request) {
    51	        List<CartItem> cart = cart(request.items());
    52	        ClubTier tier = ClubTier.fromCode(request.clubTier()).orElseThrow(() -> invalid(ErrorCode.INVALID_CLUB_TIER));
    53	        Region region = Region.fromCode(request.region()).orElseThrow(() -> invalid(ErrorCode.INVALID_REGION));
    54	        if (request.zipCode() == null || !ZIP_CODE.matcher(request.zipCode()).matches()) {
    55	            throw invalid(ErrorCode.INVALID_ZIP_CODE);
    56	        }
    57	        ShippingOption shippingOption = shippingOptions.find(request.shippingMethod())
    58	                .orElseThrow(() -> invalid(ErrorCode.INVALID_SHIPPING_METHOD));
    59	
    60	        // 1. Soma dos produtos
    61	        BigDecimal subtotal = cart.stream().map(CartItem::total).reduce(Money.ZERO, BigDecimal::add);
    62	        BigDecimal weightKg = cart.stream().map(CartItem::weightKg).reduce(BigDecimal.ZERO, BigDecimal::add);
    63	
    64	        // 3. Frete (calculado antes do cupom porque o cupom de frete depende dele)
    65	        ShippingQuote quote = shippingOption.quote(new ShippingRequest(request.zipCode(), region, weightKg, subtotal));
    66	        BigDecimal shippingCost = tier.freeShipping() && shippingOption.coveredByClubFreeShipping()
    67	                ? Money.ZERO
    68	                : Money.round(quote.cost());
    69	
    70	        // 2. Desconto do cupom
    71	        BigDecimal couponDiscount = Money.ZERO;
    72	        if (request.couponInformed()) {
    73	            Coupon coupon = coupons.find(request.coupon()).orElseThrow(() -> invalid(ErrorCode.INVALID_COUPON));
    74	            couponDiscount = coupons.discount(coupon,
    75	                    new CouponContext(request.cpf(), cart, subtotal, shippingOption, shippingCost));
    76	        }
    77	
    78	        // 4. Seguro e 5. total do pedido
    79	        BigDecimal insurance = region.insurance(subtotal);
    80	        BigDecimal orderTotal = subtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
    81	
    82	        // 6. Ajuste da forma de pagamento
    83	        PaymentMethod paymentMethod = paymentMethods.find(request.paymentMethod())
    84	                .orElseThrow(() -> invalid(ErrorCode.INVALID_PAYMENT_METHOD));
    85	        Integer installments = request.installments();
    86	        if (installments == null || !paymentMethod.acceptsInstallments(installments)) {
    87	            throw invalid(ErrorCode.INVALID_INSTALLMENTS);
    88	        }
    89	        PaymentTerms terms = paymentMethod.terms(
    90	                new PaymentContext(orderTotal, installments, request.couponInformed()));
    91	        BigDecimal finalTotal = Money.round(terms.finalTotal());
    92	
    93	        return new CheckoutSummary(
    94	                subtotal,
    95	                couponDiscount,
    96	                shippingCost,
    97	                quote.deliveryDays(),
    98	                insurance,
    99	                finalTotal.subtract(orderTotal),
   100	                finalTotal,
   101	                installments,
   102	                Money.round(terms.installmentAmount()),
   103	                tier.nextPurchaseCredit(subtotal),
   104	                tier == ClubTier.GOLD && subtotal.compareTo(Money.of("500.00")) > 0);
   105	    }
   106	
   107	    private List<CartItem> cart(List<OrderItem> items) {
   108	        Map<String, Product> catalog = products.findBySkus(items.stream().map(OrderItem::sku).toList());
   109	        if (items.stream().anyMatch(item -> !catalog.containsKey(item.sku()))) {
   110	            throw invalid(ErrorCode.UNKNOWN_PRODUCT);
   111	        }
   112	        if (items.stream().anyMatch(item -> catalog.get(item.sku()).discontinued())) {
   113	            throw invalid(ErrorCode.PRODUCT_DISCONTINUED);
   114	        }
   115	        if (items.stream().anyMatch(item -> catalog.get(item.sku()).stock() < item.quantity())) {
   116	            throw invalid(ErrorCode.INSUFFICIENT_STOCK);
   117	        }
   118	        return items.stream().map(item -> new CartItem(catalog.get(item.sku()), item.quantity())).toList();
   119	    }
   120	
   121	    private static ApiException invalid(ErrorCode code) {
   122	        return ApiException.unprocessable(code);
   123	    }
   124	}
