     3	import java.net.URI;
     4	import java.net.URLDecoder;
     5	import java.nio.charset.StandardCharsets;
     6	
     7	/**
     8	 * Aceita o endereço do banco tanto no formato JDBC ({@code jdbc:postgresql://host:5432/loja}) quanto
     9	 * no formato comum dos provedores ({@code postgres://usuario:senha@host:5432/loja}).
    10	 */
    11	record JdbcUrl(String url, String user, String password) {
    12	
    13	    static JdbcUrl parse(String raw) {
    14	        String value = raw.strip();
    15	        if (value.startsWith("jdbc:")) {
    16	            return new JdbcUrl(value, null, null);
    17	        }
    18	        if (!value.startsWith("postgres://") && !value.startsWith("postgresql://")) {
    19	            return new JdbcUrl("jdbc:" + value, null, null);
    20	        }
    21	        URI uri = URI.create(value);
    22	        String user = null;
    23	        String password = null;
    24	        if (uri.getRawUserInfo() != null) {
    25	            String[] parts = uri.getRawUserInfo().split(":", 2);
    26	            user = decode(parts[0]);
    27	            password = parts.length > 1 ? decode(parts[1]) : null;
    28	        }
    29	        String port = uri.getPort() == -1 ? "" : ":" + uri.getPort();
    30	        String path = uri.getRawPath() == null ? "" : uri.getRawPath();
    31	        String query = uri.getRawQuery() == null ? "" : "?" + uri.getRawQuery();
    32	        return new JdbcUrl("jdbc:postgresql://" + uri.getHost() + port + path + query, user, password);
    33	    }
    34	
    35	    private static String decode(String value) {
    36	        return URLDecoder.decode(value, StandardCharsets.UTF_8);
    37	    }
    38	}
