48	    28	/**
49	    29	 * Calcula o resumo da compra, conferindo os dados na ordem combinada e recusando no primeiro
50	    30	 * problema. O resumo mostrado antes de confirmar e o do pedido registrado saem daqui.
51	    31	 */
52	    32	@Service
53	    33	public class CheckoutCalculator {
54	    34	
55	    35	    private static final Pattern ZIP_CODE = Pattern.compile("\\d{8}");
56	    36	
57	    37	    private final ProductRepository products;
58	    38	    private final ShippingOptions shippingOptions;
59	    39	    private final Coupons coupons;
60	    40	    private final PaymentMethods paymentMethods;
61	    41	
62	    42	    public CheckoutCalculator(ProductRepository products, ShippingOptions shippingOptions, Coupons coupons,
63	    43	            PaymentMethods paymentMethods) {
64	    44	        this.products = products;
65	    45	        this.shippingOptions = shippingOptions;
66	    46	        this.coupons = coupons;
67	    47	        this.paymentMethods = paymentMethods;
68	    48	    }
69	    49	
70	    50	    public CheckoutSummary calculate(CheckoutRequest request) {
71	    51	        List<CartItem> cart = cart(request.items());
72	    52	        ClubTier tier = ClubTier.fromCode(request.clubTier()).orElseThrow(() -> invalid(ErrorCode.INVALID_CLUB_TIER));
73	    53	        Region region = Region.fromCode(request.region()).orElseThrow(() -> invalid(ErrorCode.INVALID_REGION));
74	    54	        if (request.zipCode() == null || !ZIP_CODE.matcher(request.zipCode()).matches()) {
75	    55	            throw invalid(ErrorCode.INVALID_ZIP_CODE);
76	    56	        }
77	    57	        ShippingOption shippingOption = shippingOptions.find(request.shippingMethod())
78	    58	                .orElseThrow(() -> invalid(ErrorCode.INVALID_SHIPPING_METHOD));
79	    59	
80	    60	        // 1. Soma dos produtos
81	    61	        BigDecimal subtotal = cart.stream().map(CartItem::total).reduce(Money.ZERO, BigDecimal::add);
82	    62	        BigDecimal weightKg = cart.stream().map(CartItem::weightKg).reduce(BigDecimal.ZERO, BigDecimal::add);
83	    63	
84	    64	        // 3. Frete (calculado antes do cupom porque o cupom de frete depende dele)
85	    65	        ShippingQuote quote = shippingOption.quote(new ShippingRequest(request.zipCode(), region, weightKg, subtotal));
86	    66	        BigDecimal shippingCost = tier.freeShipping() && shippingOption.coveredByClubFreeShipping()
87	    67	                ? Money.ZERO
88	    68	                : Money.round(quote.cost());
89	    69	
90	    70	        // 2. Desconto do cupom
91	    71	        BigDecimal couponDiscount = Money.ZERO;
92	    72	        if (request.couponInformed()) {
93	    73	            Coupon coupon = coupons.find(request.coupon()).orElseThrow(() -> invalid(ErrorCode.INVALID_COUPON));
94	    74	            couponDiscount = coupons.discount(coupon,
95	    75	                    new CouponContext(request.cpf(), cart, subtotal, shippingOption, shippingCost));
96	    76	        }
97	    77	
98	    78	        // 4. Seguro e 5. total do pedido
99	    79	        BigDecimal insurance = region.insurance(subtotal);
100	    80	        BigDecimal orderTotal = subtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
101	    81	
102	    82	        // 6. Ajuste da forma de pagamento
103	    83	        PaymentMethod paymentMethod = paymentMethods.find(request.paymentMethod())
104	    84	                .orElseThrow(() -> invalid(ErrorCode.INVALID_PAYMENT_METHOD));
105	    85	        Integer installments = request.installments();
106	    86	        if (installments == null || !paymentMethod.acceptsInstallments(installments)) {
107	    87	            throw invalid(ErrorCode.INVALID_INSTALLMENTS);
108	    88	        }
109	    89	        PaymentTerms terms = paymentMethod.terms(
110	    90	                new PaymentContext(orderTotal, installments, request.couponInformed()));
111	    91	        BigDecimal finalTotal = Money.round(terms.finalTotal());
112	    92	
113	    93	        return new CheckoutSummary(
114	    94	                subtotal,
115	    95	                couponDiscount,
116	    96	                shippingCost,
117	    97	                quote.deliveryDays(),
118	    98	                insurance,
119	    99	                finalTotal.subtract(orderTotal),
120	   100	                finalTotal,
121	   101	                installments,
122	   102	                Money.round(terms.installmentAmount()),
123	   103	                tier.nextPurchaseCredit(subtotal),
124	   104	                tier == ClubTier.GOLD && subtotal.compareTo(Money.of("500.00")) > 0);
125	   105	    }
