127	   107	    private List<CartItem> cart(List<OrderItem> items) {
128	   108	        Map<String, Product> catalog = products.findBySkus(items.stream().map(OrderItem::sku).toList());
129	   109	        if (items.stream().anyMatch(item -> !catalog.containsKey(item.sku()))) {
130	   110	            throw invalid(ErrorCode.UNKNOWN_PRODUCT);
131	   111	        }
132	   112	        if (items.stream().anyMatch(item -> catalog.get(item.sku()).discontinued())) {
133	   113	            throw invalid(ErrorCode.PRODUCT_DISCONTINUED);
134	   114	        }
135	   115	        if (items.stream().anyMatch(item -> catalog.get(item.sku()).stock() < item.quantity())) {
136	   116	            throw invalid(ErrorCode.INSUFFICIENT_STOCK);
137	   117	        }
138	   118	        return items.stream().map(item -> new CartItem(catalog.get(item.sku()), item.quantity())).toList();
139	   119	    }
