    10	/**
    11	 * Lê os corpos JSON sem recusar nada: quem decide se um campo faltou ou veio errado é a regra de
    12	 * negócio, na ordem de conferência combinada.
    13	 */
    14	@Component
    15	public class JsonBodies {
    16	
    17	    private final JsonMapper mapper;
    18	
    19	    public JsonBodies(JsonMapper mapper) {
    20	        this.mapper = mapper;
    21	    }
    22	
    23	    /** O corpo como árvore JSON; corpo vazio ou mal formado vira um nó ausente. */
    24	    public JsonNode read(String body) {
    25	        if (body == null || body.isBlank()) {
    26	            return MissingNode.getInstance();
    27	        }
    28	        try {
    29	            JsonNode node = mapper.readTree(body);
    30	            return node == null ? MissingNode.getInstance() : node;
    31	        } catch (JacksonException e) {
    32	            return MissingNode.getInstance();
    33	        }
    34	    }
    35	
    36	    /** O texto do campo, ou {@code null} se não veio, não é texto ou está em branco. */
    37	    public static String text(JsonNode node, String field) {
    38	        JsonNode value = node.path(field);
    39	        if (!value.isString()) {
    40	            return null;
    41	        }
    42	        String text = value.stringValue();
    43	        return text.isBlank() ? null : text;
    44	    }
    45	}

