     9	/** O crédito do clube entra no saldo quando o pagamento é confirmado e sai se o pedido pago é cancelado. */
    10	@Component
    11	public class ClubCreditListener implements OrderLifecycleListener {
    12	
    13	    private final CustomerRepository customers;
    14	
    15	    public ClubCreditListener(CustomerRepository customers) {
    16	        this.customers = customers;
    17	    }
    18	
    19	    @Override
    20	    public void paymentApproved(Order order) {
    21	        customers.addCredit(order.cpf(), order.summary().nextPurchaseCredit());
    22	    }
    23	
    24	    @Override
    25	    public void cancelled(Order order, OrderStatus previousStatus) {
    26	        if (previousStatus.paymentSettled()) {
    27	            customers.addCredit(order.cpf(), order.summary().nextPurchaseCredit().negate());
    28	        }
    29	    }
    30	}
